func tensorNRGBA(img *image.NRGBA) *qvae.Tensor {
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	t := qvae.NewTensor(1, 4, h, w)
	for y := 0; y < h; y++ {
		row := img.Pix[y*img.Stride:]
		for x := 0; x < w; x++ {
			for c := 0; c < 4; c++ {
